Algorithm Propina
  Define cuenta As Integer;
  Define amigos As Integer;
  Write "¿Cuánto es la cuenta?";
  Read cuenta;
  Write "¿Cuántos amigos pagan?"
  Read amigos;
  Define total As Integer <- cuenta + cuenta Div 10;
  Write "Cada uno paga: ", ceil(total / amigos);
EndAlgorithm

